struct Parts: AsyncSequence {
  let order: Order
  func makeAsyncIterator() -> Iterator { Iterator(order: order) }
  struct Iterator: AsyncIteratorProtocol {
    let order: Order
    var i = 0
    mutating func next() async -> Part? {
      guard i < order.items.count else { return nil }
      defer { i += 1 }
      return Part(corr: order.id, seq: i, body: order.items[i])
    }
  }
}
